            1 for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
            if 0 <= r + dr < h and 0 <= c + dc < w
            and grid[r + dr][c + dc] != bg
        )

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w):
                    continue
                if grid[rr][cc] != color:
                    continue

                # The endpoint touching the nearby motif is the anchor.
                # Extend the diagonal outward from the other endpoint.
                if neighbors(r, c) > neighbors(rr, cc):
                    anchor, tip = (r, c), (rr, cc)
                else:
                    anchor, tip = (rr, cc), (r, c)

                sr = tip[0] - anchor[0]
                sc = tip[1] - anchor[1]
                y, x = tip
                while 0 <= y < h and 0 <= x < w:
                    if grid[y][x] == bg:
                        out[y][x] = color
                    y += sr
                    x += sc

    return out
